using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using Staff.Characters;
namespace Staff.Traversal.Editor {
[InitializeOnLoad] public static class TangentMathVerification {
 const string W="Library/TangentMath/",K="Staff.TangentMathVerify";static double start;static int stage;static TangentEquationUI preview;static Camera camera;
 static TangentMathVerification(){EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(W+"test.request")){File.Delete(W+"test.request");File.WriteAllText(W+"result.txt","");SessionState.SetBool(K,true);EditorApplication.isPlaying=true;return;}if(!SessionState.GetBool(K,false)||!EditorApplication.isPlaying)return;if(start==0){start=EditorApplication.timeSinceStartup;return;}if(EditorApplication.timeSinceStartup-start<(stage==0?4:1))return;try{if(stage==0){Check();SetupPreview();preview.Render(preview.creationSeconds*.4f);Capture(W+"write.png");stage++;start=EditorApplication.timeSinceStartup;return;}if(stage==1){preview.Render(preview.creationSeconds);Capture(W+"symbolic.png");stage++;start=EditorApplication.timeSinceStartup;return;}if(stage==2){preview.Lock(new Vector3(0,2,0),new Vector3(5,-.01f,0));preview.Render(preview.substitutionSeconds*.25f);Capture(W+"contour-transform.png");stage++;start=EditorApplication.timeSinceStartup;return;}if(stage==3){preview.Render(preview.substitutionSeconds);Capture(W+"numeric.png");stage++;start=EditorApplication.timeSinceStartup;return;}if(stage==4){preview.Dismiss();preview.Render(preview.disappearanceSeconds*.5f);Capture(W+"uncreate.png");stage++;start=EditorApplication.timeSinceStartup;return;}Finish();}catch(Exception e){File.AppendAllText(W+"result.txt","FAIL "+e);Finish();}}
 static void Finish(){SessionState.SetBool(K,false);EditorApplication.isPlaying=false;start=0;stage=0;}
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);File.AppendAllText(W+"result.txt","PASS "+message+"\n");}
 static void Check(){var p=UnityEngine.Object.FindFirstObjectByType<AdventurePlayer>();var a=p.GetComponent<TangentTraversal>();var ui=p.GetComponent<TangentEquationUI>();var cam=p.GetComponentInParent<Staff.Shared.SharedGameplay>().cameraController;camera=cam.GetComponent<Camera>();a.Cancel();Assert(a.BeginScreenAim(camera),"Q aim begins");Assert(ui.Phase==TangentEquationUI.AnimationPhase.Writing&&!a.HasTarget,"Write begins immediately on Q, before any contact exists");ui.Render(.1f);var canvas=UnityEngine.Object.FindObjectsByType<Canvas>(FindObjectsInactive.Include,FindObjectsSortMode.None).Single(c=>c.name=="UI - Tangent equation");Assert(canvas.renderMode==RenderMode.ScreenSpaceOverlay,"Equation remains Overlay UI");Assert(ui.IsVisible,"Initial empty aim retains visible creation");a.Cancel();Assert(ui.Phase==TangentEquationUI.AnimationPhase.Erasing,"Failed/cancelled aim starts Uncreate instead of hiding");ui.Advance(.4f);Assert(!ui.IsVisible,"Uncreate completes");
 ui.BeginAim(camera,camera.pixelRect.center);ui.Advance(1);Assert(ui.Phase==TangentEquationUI.AnimationPhase.Symbolic&&!ui.HasSubstitution,"Aiming retains symbolic single equation");ui.Measure(new Vector3(0,2,0),new Vector3(3,6,4));Assert(Mathf.Abs(ui.Slope-.8f)<.0001f&&ui.Height==6&&ui.ContactX==5,"Actual slope and world height retained");ui.Measure(new Vector3(0,2,0),new Vector3(3,-.01f,4));Assert(ui.EvaluatedFormula.EndsWith("-0.01")&&!ui.EvaluatedFormula.Contains("+-"),"Negative values use subtraction");ui.Measure(Vector3.zero,Vector3.up*10);Assert(ui.Vertical&&ui.EvaluatedFormula.StartsWith("x="),"Vertical tangent supported");
 var data=JsonUtility.FromJson<TangentContourData>(Resources.Load<TextAsset>("TangentMath/contours").text);Assert(data.glyphs.Length==21&&data.writeFrames.Length==121,"Actual Manim TeX contours and Write frames exported");Assert(data.glyphs.All(g=>g.contours.All(c=>c.points.Length==128)),"Reference 128-point arc-length contours preserved");
 a.Cancel();var body=p.GetComponent<CharacterController>();body.enabled=false;p.transform.position=new Vector3(0,1000,0);body.enabled=true;var cube=GameObject.CreatePrimitive(PrimitiveType.Cube);cube.transform.position=new Vector3(10,1001,0);cube.transform.localScale=Vector3.one*2;cube.AddComponent<TangentSurface>();Physics.SyncTransforms();a.BeginScreenAim(camera);Assert(a.Aim(new Ray(p.transform.position+Vector3.up,Vector3.right)),"Wall acquired");Assert(a.Launch()&&!ui.HasSubstitution,"Casting keeps symbolic formula");a.TickMovement(.05f);a.TickMovement(.05f);Assert(ui.Phase==TangentEquationUI.AnimationPhase.Substituting,"Flight starts contour substitution");ui.Render(.3f);Assert(a.CancelWithJump()&&ui.Phase==TangentEquationUI.AnimationPhase.Erasing,"Jump cancel uncreates current morph");ui.Render(.4f);
 a.BeginScreenAim(camera);a.Aim(new Ray(p.transform.position+Vector3.up,Vector3.right));a.Launch();for(int i=0;i<100&&a.State!=TangentTraversal.Phase.Wall;i++)a.TickMovement(.016f);Assert(a.CompletedHops>0&&ui.Phase==TangentEquationUI.AnimationPhase.Erasing,"Successful arrival starts Uncreate");a.Cancel();UnityEngine.Object.DestroyImmediate(cube);body.enabled=false;p.transform.position=new Vector3(0,10000,0);body.enabled=true;camera.transform.position=p.transform.position+Vector3.up;camera.transform.rotation=Quaternion.LookRotation(Vector3.up,Vector3.forward);a.BeginScreenAim(camera);var pos=camera.transform.position;var rot=camera.transform.rotation;Assert(!a.EndScreenAim(),"Missed contact does not launch");cam.Simulate(.016f);Assert(Vector3.Distance(pos,camera.transform.position)<.001f&&Quaternion.Angle(rot,camera.transform.rotation)<.01f,"Failure camera remains continuous");var size=TangentEquationUI.DisplaySize(camera,camera.transform.position+camera.transform.forward*300);Assert(size.y>=24&&Mathf.Abs(size.x/size.y-6)<.001f,"Original 6:1 size and minimum 144x24 retained");a.BeginScreenAim(camera);Assert(ui.Phase==TangentEquationUI.AnimationPhase.Writing,"Q restarts cleanly during disappearing animation");a.Cancel();p.Respawn();
 }
 static void Capture(string path){Canvas.ForceUpdateCanvases();var graphic=UnityEngine.Object.FindFirstObjectByType<TangentContourGraphic>();var mesh=UnityEngine.Object.Instantiate(graphic.canvasRenderer.GetMesh());Assert(mesh.vertexCount>0,"Rendered UI mesh: "+System.IO.Path.GetFileName(path)+" vertices="+mesh.vertexCount);var go=new GameObject("Equation mesh capture");go.layer=31;go.transform.position=new Vector3(10000,0,0);go.AddComponent<MeshFilter>().sharedMesh=mesh;var material=new Material(Shader.Find("UI/Default"));material.SetColor("_BaseColor",Color.white);material.SetFloat("_Cull",0);go.AddComponent<MeshRenderer>().sharedMaterial=material;var cameraObject=new GameObject("Equation capture camera");var c=cameraObject.AddComponent<Camera>();c.enabled=false;c.orthographic=true;c.orthographicSize=48;c.cullingMask=1<<31;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.03f,.035f,.045f);c.transform.position=go.transform.position+Vector3.back*10;var rt=new RenderTexture(1280,384,24);var prior=RenderTexture.active;Texture2D image=null;try{c.targetTexture=rt;Staff.Rendering.StaffCameraCapture.Render(c);RenderTexture.active=rt;image=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());}finally{RenderTexture.active=prior;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(cameraObject);UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(material);UnityEngine.Object.DestroyImmediate(rt);if(image)UnityEngine.Object.DestroyImmediate(image);}}
 static void SetupPreview(){var p=UnityEngine.Object.FindFirstObjectByType<AdventurePlayer>();p.GetComponent<TangentTraversal>().enabled=false;p.enabled=false;var cam=p.GetComponentInParent<Staff.Shared.SharedGameplay>().cameraController;cam.enabled=false;camera=cam.GetComponent<Camera>();camera.transform.SetPositionAndRotation(new Vector3(5,0,-10),Quaternion.identity);camera.cullingMask=0;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.03f,.035f,.045f);preview=p.GetComponent<TangentEquationUI>();preview.enabled=false;preview.BeginAim(camera,camera.pixelRect.center);}
}
}
